merge into t_tm_stock a USING (
select #{STOCK.stockDate,jdbcType=DATE} stock_date, #{STOCK.materialCode,jdbcType=VARCHAR} material_code, #{STOCK.stockNum,jdbcType=DOUBLE} stock_num, #{STOCK.modifyNum,jdbcType=DOUBLE} modify_num, #{STOCK.badNum,jdbcType=DOUBLE} bad_num, #{STOCK.createBy,jdbcType=VARCHAR} create_by, #{STOCK.createTime,jdbcType=DATE} create_time, #{STOCK.updateBy,jdbcType=VARCHAR} update_by, #{STOCK.updateTime,jdbcType=DATE} update_time, #{STOCK.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.stock_date = b.stock_date and b.material_code = a.material_code AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.stock_num = b.stock_num, a.update_by = b.create_by, a.update_time = sysdate WHEN NOT MATCHED THEN INSERT (a.id, a.stock_date, a.material_code, a.stock_num, a.modify_num, a.bad_num, a.create_by, a.create_time, a.remark, a.del_flag) values (SEQ_TM_STOCK.NEXTVAL, b.stock_date, b.material_code, b.stock_num, b.modify_num, b.bad_num, b.create_by, sysdate, b.remark, '0')

